function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 250) return 'grid needs 1 to 250 rows.';
  const width = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (width < 1 || width > 250) return 'Each row needs 1 to 250 cells.';
  for (const row of grid) {
    if (!Array.isArray(row) || row.length !== width) return 'All rows must have the same length.';
    if (row.some((cell) => cell !== 0 && cell !== 1)) return 'Each cell is 0 or 1.';
  }
  return null;
}

