function countServers(grid) {
  // For every server, look along its row and its column for another server.
  let total = 0;
  grid.forEach((line, i) => {
    line.forEach((cell, j) => {
      if (cell !== 1) return;
      const inRow = line.some((other, k) => k !== j && other === 1);
      const inColumn = grid.some((other, k) => k !== i && other[j] === 1);
      if (inRow || inColumn) total += 1;
    });
  });
  return total;
}

