function generate(rand, size) {
  const small = size === 'small';
  const m = small ? 1 + Math.floor(rand() * 5) : 60 + Math.floor(rand() * 41);
  const n = small ? 1 + Math.floor(rand() * 5) : 60 + Math.floor(rand() * 41);
  // Sparse grids leave many servers alone; dense ones connect almost all of them.
  const densities = small ? [0.1, 0.3, 0.5, 0.9] : [0.005, 0.01, 0.03, 0.3];
  const density = densities[Math.floor(rand() * densities.length)];
  return [Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < density ? 1 : 0)))];
}
